# Usage: run.sh <scheme 0=dark|1=light> <selectors,comma,separated> <out.png>
Q="$(printf %s "$2" | sed "s/#/%23/g; s/ /%20/g")"; W="$(cd "$(dirname "$0")" && pwd -W)"; E="/c/Program Files (x86)/Microsoft/Edge/Application/msedge.exe"
[ -n "$2" ] && "$E" --headless=new --disable-gpu --hide-scrollbars --allow-file-access-from-files --blink-settings=preferredColorScheme=$1 --window-size=2643,1300 --virtual-time-budget=8000 --dump-dom "file:///$W/harness.html?m=$Q&s=$4" 2>/dev/null | grep -o 'data-m="[^"]*"' | sed 's/&quot;/"/g; s/^data-m="//; s/"$//' | "/c/Program Files/nodejs/node.exe" -e 'let s="";process.stdin.on("data",d=>s+=d).on("end",()=>{const r=JSON.parse(s);for(const[w,v] of Object.entries(r)){console.log(`@${w}`);for(const[k,b] of Object.entries(v)) console.log("   "+k.padEnd(22),b)}})'
if [ -n "$3" ]; then "$E" --headless=new --disable-gpu --hide-scrollbars --allow-file-access-from-files --blink-settings=preferredColorScheme=$1 --window-size=2643,1300 --virtual-time-budget=8000 --screenshot="$W/$3" "file:///$W/harness.html?s=$4" 2>&1 | grep -q written && echo "screenshot: $3"; fi
